def parse_simple_csv(csv_text: str) -> list[dict]:
    if not csv_text.strip():
        return []

    lines = csv_text.strip().split('\n')
    header = [h.strip() for h in lines[0].split(',')]
    data = []

    for line in lines[1:]:
        if not line.strip():
            continue

        row = {}
        fields = []
        field = ''
        in_quotes = False

        for char in line:
            if char == '"':
                in_quotes = not in_quotes
            elif char == ',' and not in_quotes:
                fields.append(field.strip())
                field = ''
            else:
                field += char

        fields.append(field.strip())

        for i, value in enumerate(fields):
            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]

            row[header[i]] = value

        data.append(row)

    return data

def safe_json_path_lookup(data: dict | list, path: str, default: any = None) -> any:
    if not path:
        return data

    components = path.split('.')
    current = data

    for component in components:
        try:
            if component.isdigit():
                current = current[int(component)]
            else:
                current = current[component]
        except (KeyError, IndexError, TypeError):
            return default

    return current

def compact_number_formatter(n: int | float) -> str:
    if n >= 1_000_000_000:
        return f"{n / 1_000_000_000:.1f}B" if n % 1_000_000_000 != 0 else f"{n / 1_000_000_000}B"
    elif n >= 1_000_000:
        return f"{n / 1_000_000:.1f}M" if n % 1_000_000 != 0 else f"{n / 1_000_000}M"
    elif n >= 1_000:
        return f"{n / 1_000:.1f}K" if n % 1_000 != 0 else f"{n / 1_000}K"
    else:
        return str(n)

def validate_password_strength(pw: str) -> dict:
    criteria = {
        'length': len(pw) >= 8,
        'uppercase': any(c.isupper() for c in pw),
        'lowercase': any(c.islower() for c in pw),
        'digit': any(c.isdigit() for c in pw),
        'special': any(c in '!@#$%^&*()-_=+[]{}' for c in pw)
    }
    score = sum(criteria.values())
    missing = [key for key, value in criteria.items() if not value]
    return {"valid": score == 5, "score": score, "missing": missing}

def time_diff_humanized(seconds: int) -> str:
    if seconds == 0:
        return "0s"

    units = [
        (86400, 'd'),
        (3600, 'h'),
        (60, 'm'),
        (1, 's')
    ]

    result = []
    for count, unit in units:
        value = seconds // count
        if value > 0:
            result.append(f"{value}{unit}")
            seconds %= count

    return ' '.join(result)

import re

def clean_phone_number(raw: str, default_country_code: str = "+94") -> str | None:
    # Remove all spaces, dashes, dots, and parentheses
    cleaned = re.sub(r'[\s-().]', '', raw)

    # Check if the cleaned number starts with '0' followed by 9 digits
    if cleaned.startswith('0') and len(cleaned) == 10:
        cleaned = default_country_code + cleaned[1:]

    # Check if the cleaned number starts with '00'
    if cleaned.startswith('00'):
        cleaned = '+' + cleaned[2:]

    # Check if the cleaned number already starts with '+'
    if cleaned.startswith('+'):
        if 10 <= len(cleaned) <= 15 and cleaned[1:].isdigit():
            return cleaned

    # If invalid length or contains unexpected non-digit characters, return None
    return None

def find_first_missing_positive(nums: list[int]) -> int:
    n = len(nums)
    if 1 not in nums:
        return 1

    # Replace negative numbers, zeros, and numbers larger than n with 1s
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = 1

    # Use index as a hash key and number sign as a presence detector
    for i in range(n):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])

    # The first positive index + 1 indicates the missing number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If all numbers are present, return n + 1
    return n + 1

def calculate_tax_bracket(income: float, brackets: list[tuple[float, float]]) -> float:
    tax = 0.0
    for upper_limit, rate in brackets:
        if income <= 0:
            break
        taxable_amount = min(income, upper_limit) - (upper_limit - brackets[brackets.index((upper_limit, rate)) - 1][0])
        tax += taxable_amount * rate
        income -= taxable_amount
    return round(tax, 2)

def fuzzy_search_score(pattern: str, text: str) -> int:
    pattern = pattern.lower()
    text = text.lower()
    score = 0
    last_index = -1

    for char in pattern:
        try:
            index = text.index(char, last_index + 1)
        except ValueError:
            return 0

        score += 10
        if index == last_index + 1:
            score += 15
        if index == 0 or text[index - 1] in " _-":
            score += 20

        last_index = index

    return score

def simple_caesar_cipher(text: str, shift: int) -> str:
    def shift_char(c: str, shift: int) -> str:
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c, shift) for c in text)

def matrix_transpose_ragged(matrix: list[list[any]], fill_value: any = None) -> list[list[any]]:
    if not matrix or all(len(row) == 0 for row in matrix):
        return []

    max_len = max(len(row) for row in matrix)
    transposed = []

    for col in range(max_len):
        transposed_row = [row[col] if col < len(row) else fill_value for row in matrix]
        transposed.append(transposed_row)

    return transposed

from itertools import groupby

def run_length_compress(data: list[int]) -> list[tuple[int, int]]:
    if not data:
        return []
    return [(key, sum(1 for _ in group)) for key, group in groupby(data)]

def parse_duration_string(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            value = int(s[i:j])
            i = j
        else:
            raise ValueError("Invalid character in string")

        if i < len(s) and s[i] in units:
            total_seconds += value * units[s[i]]
            i += 1
        else:
            raise ValueError("Invalid unit in string")

    return total_seconds

def sliding_window_median(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []

    def get_median(window):
        window.sort()
        n = len(window)
        if n % 2 == 1:
            return round(window[n // 2], 2)
        else:
            return round((window[n // 2 - 1] + window[n // 2]) / 2, 2)

    result = []
    window = nums[:k]
    result.append(get_median(window))

    for i in range(k, len(nums)):
        window.pop(0)
        window.append(nums[i])
        result.append(get_median(window))

    return result

class CircularBuffer:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.buffer = [None] * capacity
        self.head = 0
        self.tail = 0
        self.size = 0

    def enqueue(self, item: any) -> bool:
        if self.is_full():
            return False
        self.buffer[self.tail] = item
        self.tail = (self.tail + 1) % self.capacity
        self.size += 1
        return True

    def dequeue(self) -> any:
        if self.is_empty():
            raise IndexError("Buffer is empty")
        item = self.buffer[self.head]
        self.buffer[self.head] = None
        self.head = (self.head + 1) % self.capacity
        self.size -= 1
        return item

    def peek(self) -> any:
        if self.is_empty():
            raise IndexError("Buffer is empty")
        return self.buffer[self.head]

    def is_full(self) -> bool:
        return self.size == self.capacity

    def is_empty(self) -> bool:
        return self.size == 0

    def size(self) -> int:
        return self.size

def deep_merge_dicts(base: dict, update: dict) -> dict:
    result = base.copy()
    for key, value in update.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = deep_merge_dicts(result[key], value)
        else:
            result[key] = value
    return result

def retry_with_backoff_simulator(attempts_needed: int, max_retries: int, base_delay: float = 1.0, factor: float = 2.0, max_delay: float = 60.0) -> tuple[bool, float, list[float]]:
    if attempts_needed <= max_retries + 1:
        total_delay = sum(min(base_delay * (factor ** (k - 1)), max_delay) for k in range(1, attempts_needed))
        delays_list = [round(min(base_delay * (factor ** (k - 1)), max_delay), 2) for k in range(1, attempts_needed)]
        return True, total_delay, delays_list
    else:
        total_delay = sum(min(base_delay * (factor ** (k - 1)), max_delay) for k in range(1, max_retries + 1))
        delays_list = [round(min(base_delay * (factor ** (k - 1)), max_delay), 2) for k in range(1, max_retries + 1)]
        return False, total_delay, delays_list

def evaluate_simple_expression(expr: str) -> int:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            values.append(int(left / right))

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        return precedence[op1] > precedence[op2]

    expr = expr.replace(" ", "")
    values = []
    operators = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            values.append(int(expr[i:j]))
            i = j
        elif expr[i] in "+-*/":
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], expr[i])):
                apply_operator(operators, values)
            operators.append(expr[i])
            i += 1
        elif expr[i] == '(':
            operators.append(expr[i])
            i += 1
        elif expr[i] == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
            i += 1
    while operators:
        apply_operator(operators, values)
    return values[0]
